CREATE TABLE IF NOT EXISTS scientific_apparatus (apparatus_id uuid PRIMARY KEY, actor_sid text NOT NULL, name text NOT NULL, draft_content jsonb NOT NULL, draft_token bigint NOT NULL DEFAULT 1, latest_revision_id uuid, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS scientific_apparatus_revisions (revision_id uuid PRIMARY KEY, apparatus_id uuid NOT NULL REFERENCES scientific_apparatus(apparatus_id), revision_name text NOT NULL, content_hash text NOT NULL, canonical_content jsonb NOT NULL, actor_sid text NOT NULL, recorded_at timestamptz NOT NULL, UNIQUE(apparatus_id, revision_name));
CREATE TABLE IF NOT EXISTS scientific_operations (actor_sid text NOT NULL, operation_kind text NOT NULL, operation_id uuid NOT NULL, resource_id uuid NOT NULL, payload jsonb NOT NULL, recorded_at timestamptz NOT NULL, PRIMARY KEY(actor_sid, operation_kind, operation_id));
REVOKE INSERT, UPDATE, DELETE, TRUNCATE ON scientific_apparatus, scientific_apparatus_revisions, scientific_operations FROM PUBLIC;
